package domain

// ---- Delegate ingestion (single entry and CSV import) ---------------------------

// ParticipantCreateRequest is the body of POST /api/v1/admin/participants/create.
// The membership ID and QR signature are generated by the server.
type ParticipantCreateRequest struct {
	FullName    string `json:"full_name"`
	Email       string `json:"email"`
	TeamName    string `json:"team_name"`
	DateOfBirth string `json:"date_of_birth"` // YYYY-MM-DD, optional
	VenueID     string `json:"venue_id"`      // optional
}

// NewParticipant is one validated delegate ready to insert. Email is
// lower-cased; empty strings mean "not given" and are stored as NULL.
type NewParticipant struct {
	Line        int // CSV line number (1 = header); 0 for single entry
	FullName    string
	Email       string
	TeamName    string
	DateOfBirth string // YYYY-MM-DD
	VenueID     string
}

// CreatedParticipant is a delegate the ingestion just inserted.
type CreatedParticipant struct {
	Line         int    `json:"line,omitempty"`
	ID           string `json:"id"`
	MembershipID string `json:"membership_id"`
	FullName     string `json:"full_name"`
	Email        string `json:"email"`
	TeamName     string `json:"team_name"`
	DateOfBirth  string `json:"date_of_birth,omitempty"`
	VenueID      string `json:"venue_id,omitempty"`
	QRSignature  string `json:"qr_signature"`
}

// ImportIssue is one CSV row that was not imported.
type ImportIssue struct {
	Line    int    `json:"line"`
	Email   string `json:"email,omitempty"`
	Message string `json:"message"`
}

// ImportResult is the response of POST /api/v1/admin/participants/upload-csv.
// Every data row ends up in exactly one of Created, Duplicates or Errors.
type ImportResult struct {
	TotalRows  int                  `json:"total_rows"`
	Created    []CreatedParticipant `json:"created"`
	Duplicates []ImportIssue        `json:"duplicates"` // email already registered, or repeated in the file
	Errors     []ImportIssue        `json:"errors"`     // invalid rows, fix and upload again
}

// Ingestion limits.
const (
	MaxParticipantNameLen  = 150 // participants.full_name
	MaxParticipantTeamLen  = 150 // participants.team_name
	MaxParticipantEmailLen = 255 // participants.email
	MaxImportRows          = 10000
	MaxImportBytes         = 5 << 20
)
